import json,numpy as np
m=json.load(open('/app/output/initial/meta.json'))
for cam,pts in {'topview':[(191,74),(202,74),(215,74),(190,62),(190,52),(120,47)],'right':[(174,124),(174,116),(190,115)],'left':[(149,87)]}.items():
 d=np.load('/app/output/initial/depth_'+cam+'.npy'); c=m['cameras'][cam]; K=np.array(c['intrinsic_cv']); M=np.array(c['cam2world_gl']);
 for u,v in pts:
  z=float(d[v,u]); p=np.array([(u-K[0,2])*z/K[0,0],-(v-K[1,2])*z/K[1,1],-z,1]); print(cam,(u,v),'depth',z,'xyz',(M@p)[:3])
